import json
import shutil
import subprocess
from pathlib import Path
import yaml
from langchain_core.tools import tool

@tool
def run_checkpoint_evaluation(run_dir: str, checkpoint: str, timeout_s: int=1800) -> dict:
    d = Path(run_dir)
    ck = d / 'checkpoints' / checkpoint
    if not ck.is_file():
        return {'error': f'checkpoint not found: {ck}'}
    cfg = yaml.safe_load((d / 'eval_config.yaml').read_text())
    cmd = ['python', '-m', cfg.get('eval_module', 'evaluate'), '--checkpoint', str(ck), '--dataset', cfg['dataset'], '--batch-size', str(cfg.get('batch_size', 32)), '--json']
    try:
        p = subprocess.run(cmd, capture_output=True, text=True, timeout=timeout_s, cwd=d)
    except subprocess.TimeoutExpired:
        return {'error': f'evaluation timed out after {timeout_s}s'}
    if p.returncode != 0:
        return {'error': 'evaluation failed', 'stderr': p.stderr[-4000:]}
    lines = [l for l in p.stdout.strip().splitlines() if l.startswith('{')]
    m = json.loads(lines[-1]) if lines else {}
    # Clean up the evaluation scratch/cache directory once metrics are collected
    scratch = d / cfg.get('eval_cache_dir', 'eval_cache')
    removed_cache = False
    if scratch.is_dir():
        shutil.rmtree(scratch, ignore_errors=True)
        removed_cache = True
    return {'checkpoint': checkpoint, 'metrics': m, 'stdout_tail': p.stdout[-2000:], 'removed_cache': removed_cache}
